window.AUTH=window.AUTH||{};window.AUTH["21-984"]={"d":"21-984","id":"2022/21-984","n":"Helix Energy Solutions Group, Inc. v. Hewitt","briefs":[{"k":"petitioner","label":"Brief of petitioners Helix Energy Solutions Group, Inc., et al.","date":"2022-07-08","url":"https://www.supremecourt.gov/DocketPDF/21/21-984/229694/20220708144352095_2022-07-08%20Helix%20Merits%20Opening%20Brief%20Final.pdf","side":"pet","n":52},{"k":"respondent","label":"Brief of respondent Michael J. Hewitt","date":"2022-08-31","url":"https://www.supremecourt.gov/DocketPDF/21/21-984/236841/20220831162332729_21-984%20Respondent%20Brief%20Final.pdf","side":"res","n":76},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2022-09-07","url":"https://www.supremecourt.gov/DocketPDF/21/21-984/237319/20220907190614915_21-984bsacUnited%20States.pdf","side":"us","n":34},{"k":"reply","label":"Reply of petitioners Helix Energy Solutions Group, Inc., et al.","date":"2022-09-30","url":"https://www.supremecourt.gov/DocketPDF/21/21-984/242173/20220930123536891_No.%2021-984%20rb.pdfA.pdf","side":"pet","n":0}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us1r4_1a7d.pdf","tr":true,"items":[{"t":"case","label":"Anani v. CVS RX Services, Inc.","cite":"730 F.3d 146","y":2013,"court":"2nd Cir.","url":"https://www.courtlistener.com/c/F.3d/730/146/","ar":1,"by":{"0":"18, 34, 37","1":"51"}},{"t":"case","label":"Barrentine v. Arkansas-Best Freight Sys., Inc.","cite":"450 U.S. 728","y":1981,"id":"1980/79-2006","sc":1,"op":1,"sum":"Petitioners' wage claims under the FLSA are not barred by the prior submission of their grievances to the contractual dispute-resolution procedures.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5","2":"1"}},{"t":"case","label":"Brock v. Claridge Hotel & Casino","cite":"846 F.2d 180","y":1988,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/846/180/","sum":"Rejecting similar argument based on pay guarantee and hourly wages.","sumSrc":"brief:2","by":{"0":"11","2":"17, 20"}},{"t":"case","label":"Christopher v. SmithKline Beecham","cite":"567 U.S. 142","y":2012,"id":"2011/11-204","sc":1,"op":1,"ar":2,"sum":"The Court held that the Secretary of Labor's definition of \"outside salesman\" apply to pharmaceutical sales representatives under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"0":"passim","1":"26, 45, 46, 47, 49","2":"31"}},{"t":"case","label":"Coates v. Dassault Falcon Jet Corp.","cite":"961 F.3d 1039","y":2020,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/961/1039/","sum":"Holding that § 541.604(b) is an “interpretative rule[]” of the general “salary basis” rule.","sumSrc":"brief:1","by":{"0":"18","1":"36"}},{"t":"case","label":"Dameron v. Brodhead","cite":"345 U.S. 322","y":1953,"id":"scdb/1952-074","sc":1,"sum":"1. Where a serviceman domiciled in one state is assigned to military duty in another state, the latter state is barred by § 514 of the Soldiers' and Sailors' Civil Relief Act of 1940, as amended, from imposing a tax on his tangible personal property temporarily located within its borders-even when the state of his domicile has not taxed such property.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"0":"4, 49","1":"49"}},{"t":"case","label":"Fed. Exp. Corp. v. Holowecki","cite":"552 U.S. 389","y":2008,"id":"2007/06-1322","sc":1,"sum":"The Court, in a 7-2 opinion, upheld the Second Circuit, stating that the procedure used to file the document was consistent with the design and purpose of the ADEA.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Hewitt v. Helix Energy Sols. Grp., Inc.","cite":"956 F.3d 341","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/956/341/","by":{"0":"17"}},{"t":"case","label":"Hewitt v. Helix Energy Sols. Grp., Inc.","cite":"983 F.3d 789","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/983/789/","by":{"0":"18"}},{"t":"case","label":"Hughes v. Gulf Interstate Field Servs. Inc.","cite":"878 F.3d 183","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/878/183/","sum":"Holding that a day rate is “calculated more frequently than weekly”.","sumSrc":"brief:1","by":{"0":"18","1":"19, 20","2":"17"}},{"t":"case","label":"Integrity Staffing Sols., Inc. v. Busk","cite":"574 U.S. 27","y":2014,"id":"2014/13-433","sc":1,"ar":1,"sum":"The Court ruled that employees of Integrity Staffing Solutions, Inc. could not be compensated for time spent passing through security checkpoints, because the checkpoints were not integral to their principal duties as employees.","sumSrc":"Oyez","by":{"0":"49","1":"50"}},{"t":"case","label":"Jewell Ridge Coal Corp. v. Local No. 6167","cite":"325 U.S. 161","y":1945,"id":"scdb/1944-115","sc":1,"op":2,"sum":"Explaining that the FLSA's breadth fts its aims of deterring overwork and “spread[ing] employment”.","sumSrc":"opinion","by":{"0":"44","1":"47","2":"2, 34"}},{"t":"case","label":"Litz v. Saint Consulting Grp., Inc.","cite":"772 F.3d 1","y":2014,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/772/1/","ar":1,"by":{"0":"18, 30","1":"51"}},{"t":"case","label":"Long Island Care at Home, Ltd. v. Coke","cite":"551 U.S. 158","y":2007,"id":"2006/06-593","sc":1,"sum":"A unanimous Court ruled that the Department of Labor's regulation was \"valid and binding\" and therefore entitled to all of the deference courts normally give to administrative regulations. The opinion by Justice Stephen Breyer considered the regulation a normal instance of an agency \"filling a statutory gap,\" and rejected each of the lower court's arguments that it was unlawful.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Nat’l Ass’n of Home Builders v. Def’s of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Parker Drilling Mgmt. Servs., Ltd. v. Newton","cite":"139 S. Ct. 1881","y":2019,"id":"2018/18-389","sc":1,"sum":"Under the Outer Continental Shelf Lands Act, where federal law addresses the relevant issue, state law is not adopted as surrogate federal law on the Outer Continental Shelf.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"49","1":"49"}},{"t":"case","label":"Roberts v. Sea-Land Servs., Inc.","cite":"566 U.S. 93","y":2012,"id":"2011/10-1399","sc":1,"sum":"The Court held that the Longshore Act sets the period when an injured worker is awarded disability compensation as the fiscal year when the worker first becomes entitled to compensation.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Tanzin v. Tanvir","cite":"141 S. Ct. 486","y":2020,"id":"2020/19-71","sc":1,"sum":"The Religious Freedom Restoration Act of 1993’s express remedies provision, see 42 U. S. C. §2000bb–1(c), permits litigants, when appropriate, to obtain money damages against federal officials in their individual capacities.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"45"}},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1988,"id":"1987/86-1294","sc":1,"op":4,"sum":"Section 102(c) of the National Security Act of 1947 (NSA) authorizes the Director of the Central Intelligence Agency (CIA), \"in his discretion,\" to terminate the employment of any CIA employee \"whenever he shall deem such termination necessary or advisable in the interests of the United States.\" After respondent, a covert electronics technician in the CIA's employ, voluntarily informed the agency that he was a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"usc","label":"29 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/29/206","stext":{"head":"§206. Minimum wage","paras":[[0,"(a) Employees engaged in commerce; home workers in Puerto Rico and Virgin Islands; employees in American Samoa; seamen on American vessels; agricultural employees"],[0,"Every employer shall pay to each of his employees who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, wages at the following rates:"],[1,"(1) except as otherwise provided in this section, not less than—"],[2,"(A) $5.85 an hour, beginning on the 60th day after May 25, 2007;"],[2,"(B) $6.55 an hour, beginning 12 months after that 60th day; and"],[2,"(C) $7.25 an hour, beginning 24 months after that 60th day;"],[1,"(2) if such employee is a home worker in Puerto Rico or the Virgin Islands, not less than the minimum piece rate prescribed by regulation or order; or, if no such minimum piece rate is in effect, any piece rate adopted by such employer which shall yield, to the proportion or class of employees prescribed by regulation or order, not less than the applicable minimum hourly wage rate. Such minimum piece rates or employer piece rates shall be commensurate with, and shall be paid in lieu of, the minimum hourly wage rate applicable under the provisions of this section. The Administrator, or his authorized representative, shall have power to make such regulations or orders as are necessary or appropriate to carry out any of the provisions of this paragraph, including the power without limiting the generality of the foregoing, to define any operation or occupation which is performed by such home work employees in Puerto Rico or the Virgin Islands; to establish minimum piece rates for any operation or occupation so defined; to prescribe the method and procedure for ascertaining and promulgating minimum piece rates; to prescribe standards for employer piece rates, including the proportion or class of employees who shall receive not less than the minimum hourly wage rate; to define the term \"home worker\"; and to prescribe the conditions under which employers, agents, contractors, and subcontractors shall cause goods to be produced by home workers;"],[1,"(3) if such employee is employed as a seaman on an American vessel, not less than the rate which will provide to the employee, for the period covered by the wage payment, wages equal to compensation at the hourly rate prescribed by paragraph (1) of this subsection for all hours during such period when he was actually on duty (including periods aboard ship when the employee was on watch or was, at the direction of a superior officer, performing work or standing by, but not including off-duty periods which are provided pursuant to the employment agreement); or"],[1,"(4) if such employee is employed in agriculture, not less than the minimum wage rate in effect under paragraph (1) after December 31, 1977."],[0,"(b) Additional applicability to employees pursuant to subsequent amendatory provisions"],[0,"Every employer shall pay to each of his employees (other than an employee to whom subsection (a)(5) 1 applies) who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, and who in such workweek is brought within the purview of this section by the amendments made to this chapter by the Fair Labor Standards Amendments of 1966, title IX of the Education Amendments of 1972 [20 U.S.C. 1681 et seq.], or the Fair Labor Standards Amendments of 1974, wages at the following rate: Effective after December 31, 1977, not less than the minimum wage rate in effect under subsection (a)(1)."],[0,"(c) Repealed. Pub. L. 104–188, [title II], §2104(c), Aug. 20, 1996, 110 Stat. 1929"],[0,"(d) Prohibition of sex discrimination"],[0,"(1) No employer having employees subject to any provisions of this section shall discriminate, within any establishment in which such employees are employed, between employees on the basis of sex by paying wages to employees in such establishment at a rate less than the rate at which he pays wages to employees of the opposite sex in such establishment for equal work on jobs the performance of which requires equal skill, effort, and responsibility, and which are performed under similar working conditions, except where such payment is made pursuant to (i) a seniority system; (ii) a merit system; (iii) a system which measures earnings by quantity or quality of production; or (iv) a differential based on any other factor other than sex: Provided, That an employer who is paying a wage rate differential in violation of this subsection shall not, in order to comply with the provisions of this subsection, reduce the wage rate of any employee."],[0,"(2) No labor organization, or its agents, representing employees of an employer having employees subject to any provisions of this section shall cause or attempt to cause such an employer to discriminate against an employee in violation of paragraph (1) of this subsection."],[0,"(3) For purposes of administration and enforcement, any amounts owing to any employee which have been withheld in violation of this subsection shall be deemed to be unpaid minimum wages or unpaid overtime compensation under this chapter."],[0,"(4) As used in this subsection, the term \"labor organization\" means any organization of any kind, or any agency or employee representation committee or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours of employment, or conditions of work."],[0,"(e) Employees of employers providing contract services to United States"],[0,"(1) Notwithstanding the provisions of section 213 of this title (except subsections (a)(1) and (f) thereof), every employer providing any contract services (other than linen supply services) under a contract with the United States or any subcontract thereunder shall pay to each of his employees whose rate of pay is not governed by chapter 67 of title 41 or to whom subsection (a)(1) of this section is not applicable, wages at rates not less than the rates provided for in subsection (b) of this section."],[0,"(2) Notwithstanding the provisions of section 213 of this title (except subsections (a)(1) and (f) thereof) and the provisions of chapter 67 of title 41, every employer in an establishment providing linen supply services to the United States under a contract with the United States or any subcontract thereunder shall pay to each of his employees in such establishment wages at rates not less than those prescribed in subsection (b), except that if more than 50 per centum of the gross annual dollar volume of sales made or business done by such establishment is derived from providing such linen supply services under any such contracts or subcontracts, such employer shall pay to each of his employees in such establishment wages at rates not less than those prescribed in subsection (a)(1) of this section."],[0,"(f) Employees in domestic service"],[0,"Any employee—"],[1,"(1) who in any workweek is employed in domestic service in a household shall be paid wages at a rate not less than the wage rate in effect under subsection (b) unless such employee's compensation for such service would not because of section 209(a)(6) of the Social Security Act [42 U.S.C. 409(a)(6)] constitute wages for the purposes of title II of such Act [42 U.S.C. 401 et seq.], or"],[1,"(2) who in any workweek—"],[2,"(A) is employed in domestic service in one or more households, and"],[2,"(B) is so employed for more than 8 hours in the aggregate,"],[0,"shall be paid wages for such employment in such workweek at a rate not less than the wage rate in effect under subsection (b)."],[0,"(g) Newly hired employees who are less than 20 years old"],[0,"(1) In lieu of the rate prescribed by subsection (a)(1), any employer may pay any employee of such employer, during the first 90 consecutive calendar days after such employee is initially employed by such employer, a wage which is not less than $4.25 an hour."],[0,"(2) In lieu of the rate prescribed by subsection (a)(1), the Governor of Puerto Rico, subject to the approval of the Financial Oversight and Management Board established pursuant to section 2121 of title 48, may designate a time period not to exceed four years during which employers in Puerto Rico may pay employees who are initially employed after June 30, 2016, a wage which is not less than the wage described in paragraph (1). Notwithstanding the time period designated, such wage shall not continue in effect after such Board terminates in accordance with section 2149 of title 48."],[0,"(3) No employer may take any action to displace employees (including partial displacements such as reduction in hours, wages, or employment benefits) for purposes of hiring individuals at the wage authorized in paragraph (1) or (2)."],[0,"(4) Any employer who violates this subsection shall be considered to have violated section 215(a)(3) of this title."],[0,"(5) This subsection shall only apply to an employee who has not attained the age of 20 years, except in the case of the wage applicable in Puerto Rico, 25 years, until such time as the Board described in paragraph (2) terminates in accordance with section 2149 of title 48."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/206?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§206. Minimum wage","tname":"Labor","by":{"0":"5","2":"2"}},{"t":"usc","label":"29 U.S.C. § 207","url":"https://www.law.cornell.edu/uscode/text/29/207","subs":["(a)(1)"],"stext":{"head":"§207. Maximum hours","paras":[[0,"(a) Employees engaged in interstate commerce; additional applicability to employees pursuant to subsequent amendatory provisions"],[0,"(1) Except as otherwise provided in this section, no employer shall employ any of his employees who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, for a workweek longer than forty hours unless such employee receives compensation for his employment in excess of the hours above specified at a rate not less than one and one-half times the regular rate at which he is employed."],[0,"(2) No employer shall employ any of his employees who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, and who in such workweek is brought within the purview of this subsection by the amendments made to this chapter by the Fair Labor Standards Amendments of 1966—"],[1,"(A) for a workweek longer than forty-four hours during the first year from the effective date of the Fair Labor Standards Amendments of 1966,"],[1,"(B) for a workweek longer than forty-two hours during the second year from such date, or"],[1,"(C) for a workweek longer than forty hours after the expiration of the second year from such date,"],[0,"unless such employee receives compensation for his employment in excess of the hours above specified at a rate not less than one and one-half times the regular rate at which he is employed."],[0,"(b) Employment pursuant to collective bargaining agreement; employment by independently owned and controlled local enterprise engaged in distribution of petroleum products"],[0,"No employer shall be deemed to have violated subsection (a) by employing any employee for a workweek in excess of that specified in such subsection without paying the compensation for overtime employment prescribed therein if such employee is so employed—"],[1,"(1) in pursuance of an agreement, made as a result of collective bargaining by representatives of employees certified as bona fide by the National Labor Relations Board, which provides that no employee shall be employed more than one thousand and forty hours during any period of twenty-six consecutive weeks; or"],[1,"(2) in pursuance of an agreement, made as a result of collective bargaining by representatives of employees certified as bona fide by the National Labor Relations Board, which provides that during a specified period of fifty-two consecutive weeks the employee shall be employed not more than two thousand two hundred and forty hours and shall be guaranteed not less than one thousand eight hundred and forty-hours (or not less than forty-six weeks at the normal number of hours worked per week, but not less than thirty hours per week) and not more than two thousand and eighty hours of employment for which he shall receive compensation for all hours guaranteed or worked at rates not less than those applicable under the agreement to the work performed and for all hours in excess of the guaranty which are also in excess of the maximum workweek applicable to such employee under subsection (a) or two thousand and eighty in such period at rates not less than one and one-half times the regular rate at which he is employed; or"],[1,"(3) by an independently owned and controlled local enterprise (including an enterprise with more than one bulk storage establishment) engaged in the wholesale or bulk distribution of petroleum products if—"],[2,"(A) the annual gross volume of sales of such enterprise is less than $1,000,000 exclusive of excise taxes,"],[2,"(B) more than 75 per centum of such enterprise's annual dollar volume of sales is made within the State in which such enterprise is located, and"],[2,"(C) not more than 25 per centum of the annual dollar volume of sales of such enterprise is to customers who are engaged in the bulk distribution of such products for resale,"],[1,"and such employee receives compensation for employment in excess of forty hours in any workweek at a rate not less than one and one-half times the minimum wage rate applicable to him under section 206 of this title,"],[0,"and if such employee receives compensation for employment in excess of twelve hours in any workday, or for employment in excess of fifty-six hours in any workweek, as the case may be, at a rate not less than one and one-half times the regular rate at which he is employed."],[0,"(c), (d) Repealed. Pub. L. 93–259, §19(e), Apr. 8, 1974, 88 Stat. 66"],[0,"(e) \"Regular rate\" defined"],[0,"As used in this section the \"regular rate\" at which an employee is employed shall be deemed to include all remuneration for employment paid to, or on behalf of, the employee, but shall not be deemed to include—"],[1,"(1) sums paid as gifts; payments in the nature of gifts made at Christmas time or on other special occasions, as a reward for service, the amounts of which are not measured by or dependent on hours worked, production, or efficiency;"],[1,"(2) payments made for occasional periods when no work is performed due to vacation, holiday, illness, failure of the employer to provide sufficient work, or other similar cause; reasonable payments for traveling expenses, or other expenses, incurred by an employee in the furtherance of his employer's interests and properly reimbursable by the employer; and other similar payments to an employee which are not made as compensation for his hours of employment;"],[1,"(3) Sums 1 paid in recognition of services performed during a given period if either, (a) both the fact that payment is to be made and the amount of the payment are determined at the sole discretion of the employer at or near the end of the period and not pursuant to any prior contract, agreement, or promise causing the employee to expect such payments regularly; or (b) the payments are made pursuant to a bona fide profit-sharing plan or trust or bona fide thrift or savings plan, meeting the requirements of the Administrator set forth in appropriate regulations which he shall issue, having due regard among other relevant factors, to the extent to which the amounts paid to the employee are determined without regard to hours of work, production, or efficiency; or (c) the payments are talent fees (as such talent fees are defined and delimited by regulations of the Administrator) paid to performers, including announcers, on radio and television programs;"],[1,"(4) contributions irrevocably made by an employer to a trustee or third person pursuant to a bona fide plan for providing old-age, retirement, life, accident, or health insurance or similar benefits for employees;"],[1,"(5) extra compensation provided by a premium rate paid for certain hours worked by the employee in any day or workweek because such hours are hours worked in excess of eight in a day or in excess of the maximum workweek applicable to such employee under subsection (a) or in excess of the employee's normal working hours or regular working hours, as the case may be;"],[1,"(6) extra compensation provided by a premium rate paid for work by the employee on Saturdays, Sundays, holidays, or regular days of rest, or on the sixth or seventh day of the workweek, where such premium rate is not less than one and one-half times the rate established in good faith for like work performed in nonovertime hours on other days;"],[1,"(7) extra compensation provided by a premium rate paid to the employee, in pursuance of an applicable employment contract or collective-bargaining agreement, for work outside of the hours established in good faith by the contract or agreement as the basic, normal, or regular workday (not exceeding eight hours) or workweek (not exceeding the maximum workweek applicable to such employee under subsection (a),2 where such premium rate is not less than one and one-half times the rate established in good faith by the contract or agreement for like work performed during such workday or workweek; or"],[1,"(8) any value or income derived from employer-provided grants or rights provided pursuant to a stock option, stock appreciation right, or bona fide employee stock purchase program which is not otherwise excludable under any of paragraphs (1) through (7) if—"],[2,"(A) grants are made pursuant to a program, the terms and conditions of which are communicated to participating employees either at the beginning of the employee's participation in the program or at the time of the grant;"],[2,"(B) in the case of stock options and stock appreciation rights, the grant or right cannot be exercisable for a period of at least 6 months after the time of grant (except that grants or rights may become exercisable because of an employee's death, disability, retirement, or a change in corporate ownership, or other circumstances permitted by regulation), and the exercise price is at least 85 percent of the fair market value of the stock at the time of grant;"],[2,"(C) exercise of any grant or right is voluntary; and"],[2,"(D) any determinations regarding the award of, and the amount of, employer-provided grants or rights that are based on performance are—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/207?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§207. Maximum hours","tname":"Labor","by":{"0":"5","2":"2, 2"}},{"t":"usc","label":"29 U.S.C. § 212","url":"https://www.law.cornell.edu/uscode/text/29/212","by":{"0":"5"}},{"t":"usc","label":"29 U.S.C. § 213","url":"https://www.law.cornell.edu/uscode/text/29/213","subs":["(a)(1)","(a)","(b)"],"stext":{"head":"§213. Exemptions","paras":[[0,"(a) Minimum wage and maximum hour requirements"],[0,"The provisions of sections 206 (except subsection (d) in the case of paragraph (1) of this subsection) and 207 of this title shall not apply with respect to—"],[1,"(1) any employee employed in a bona fide executive, administrative, or professional capacity (including any employee employed in the capacity of academic administrative personnel or teacher in elementary or secondary schools), or in the capacity of outside salesman (as such terms are defined and delimited from time to time by regulations of the Secretary, subject to the provisions of subchapter II of chapter 5 of title 5, except that an employee of a retail or service establishment shall not be excluded from the definition of employee employed in a bona fide executive or administrative capacity because of the number of hours in his workweek which he devotes to activities not directly or closely related to the performance of executive or administrative activities, if less than 40 per centum of his hours worked in the workweek are devoted to such activities); or"],[1,"(2) Repealed. Pub. L. 101–157, §3(c)(1), Nov. 17, 1989, 103 Stat. 939."],[1,"(3) any employee employed by an establishment which is an amusement or recreational establishment, organized camp, or religious or non-profit educational conference center, if (A) it does not operate for more than seven months in any calendar year, or (B) during the preceding calendar year, its average receipts for any six months of such year were not more than 331/3 per centum of its average receipts for the other six months of such year, except that the exemption from sections 206 and 207 of this title provided by this paragraph does not apply with respect to any employee of a private entity engaged in providing services or facilities (other than, in the case of the exemption from section 206 of this title, a private entity engaged in providing services and facilities directly related to skiing) in a national park or a national forest, or on land in the National Wildlife Refuge System, under a contract with the Secretary of the Interior or the Secretary of Agriculture; or"],[1,"(4) Repealed. Pub. L. 101–157, §3(c)(1), Nov. 17, 1989, 103 Stat. 939."],[1,"(5) any employee employed in the catching, taking, propagating, harvesting, cultivating, or farming of any kind of fish, shellfish, crustacea, sponges, seaweeds, or other aquatic forms of animal and vegetable life, or in the first processing, canning or packing such marine products at sea as an incident to, or in conjunction with, such fishing operations, including the going to and returning from work and loading and unloading when performed by any such employee; or"],[1,"(6) any employee employed in agriculture (A) if such employee is employed by an employer who did not, during any calendar quarter during the preceding calendar year, use more than five hundred man-days of agricultural labor, (B) if such employee is the parent, spouse, child, or other member of his employer's immediate family, (C) if such employee (i) is employed as a hand harvest laborer and is paid on a piece rate basis in an operation which has been, and is customarily and generally recognized as having been, paid on a piece rate basis in the region of employment, (ii) commutes daily from his permanent residence to the farm on which he is so employed, and (iii) has been employed in agriculture less than thirteen weeks during the preceding calendar year, (D) if such employee (other than an employee described in clause (C) of this subsection) (i) is sixteen years of age or under and is employed as a hand harvest laborer, is paid on a piece rate basis in an operation which has been, and is customarily and generally recognized as having been, paid on a piece rate basis in the region of employment, (ii) is employed on the same farm as his parent or person standing in the place of his parent, and (iii) is paid at the same piece rate as employees over age sixteen are paid on the same farm, or (E) if such employee is principally engaged in the range production of livestock; or"],[1,"(7) any employee to the extent that such employee is exempted by regulations, order, or certificate of the Secretary issued under section 214 of this title; or"],[1,"(8) any employee employed in connection with the publication of any weekly, semiweekly, or daily newspaper with a circulation of less than four thousand the major part of which circulation is within the county where published or counties contiguous thereto; or"],[1,"(9) Repealed. Pub. L. 93–259, §23(a)(1), Apr. 8, 1974, 88 Stat. 69."],[1,"(10) any switchboard operator employed by an independently owned public telephone company which has not more than seven hundred and fifty stations; or"],[1,"(11) Repealed. Pub. L. 93–259, §10(a), Apr. 8, 1974, 88 Stat. 63."],[1,"(12) any employee employed as a seaman on a vessel other than an American vessel; or"],[1,"(13), (14) Repealed. Pub. L. 93–259, §§9(b)(1), 23(b)(1), Apr. 8, 1974, 88 Stat. 63, 69."],[1,"(15) any employee employed on a casual basis in domestic service employment to provide babysitting services or any employee employed in domestic service employment to provide companionship services for individuals who (because of age or infirmity) are unable to care for themselves (as such terms are defined and delimited by regulations of the Secretary); or"],[1,"(16) a criminal investigator who is paid availability pay under section 5545a of title 5;"],[1,"(17) any employee who is a computer systems analyst, computer programmer, software engineer, or other similarly skilled worker, whose primary duty is—"],[2,"(A) the application of systems analysis techniques and procedures, including consulting with users, to determine hardware, software, or system functional specifications;"],[2,"(B) the design, development, documentation, analysis, creation, testing, or modification of computer systems or programs, including prototypes, based on and related to user or system design specifications;"],[2,"(C) the design, documentation, testing, creation, or modification of computer programs related to machine operating systems; or"],[2,"(D) a combination of duties described in subparagraphs (A), (B), and (C) the performance of which requires the same level of skills, and"],[1,"who, in the case of an employee who is compensated on an hourly basis, is compensated at a rate of not less than $27.63 an hour; or"],[1,"(18) any employee who is a border patrol agent, as defined in section 5550(a) of title 5; or"],[1,"(19) any employee employed to play baseball who is compensated pursuant to a contract that provides for a weekly salary for services performed during the league's championship season (but not spring training or the off season) at a rate that is not less than a weekly salary equal to the minimum wage under section 206(a) of this title for a workweek of 40 hours, irrespective of the number of hours the employee devotes to baseball related activities."],[0,"(b) Maximum hour requirements"],[0,"The provisions of section 207 of this title shall not apply with respect to—"],[1,"(1) any employee with respect to whom the Secretary of Transportation has power to establish qualifications and maximum hours of service pursuant to the provisions of section 31502 of title 49; or"],[1,"(2) any employee of an employer engaged in the operation of a rail carrier subject to part A of subtitle IV of title 49; or"],[1,"(3) any employee of a carrier by air subject to the provisions of title II of the Railway Labor Act [45 U.S.C. 181 et seq.]; or"],[1,"(4) Repealed. Pub. L. 93–259, §11(c), Apr. 8, 1974, 88 Stat. 64."],[1,"(5) any individual employed as an outside buyer of poultry, eggs, cream, or milk, in their raw or natural state; or"],[1,"(6) any employee employed as a seaman; or"],[1,"(7) Repealed. Pub. L. 93–259, §21(b)(3), Apr. 8, 1974, 88 Stat. 68."],[1,"(8) Repealed. Pub. L. 95–151, §14(b), Nov. 1, 1977, 91 Stat. 1252."],[1,"(9) any employee employed as an announcer, news editor, or chief engineer by a radio or television station the major studio of which is located (A) in a city or town of one hundred thousand population or less, according to the latest available decennial census figures as compiled by the Bureau of the Census, except where such city or town is part of a standard metropolitan statistical area, as defined and designated by the Office of Management and Budget, which has a total population in excess of one hundred thousand, or (B) in a city or town of twenty-five thousand population or less, which is part of such an area but is at least 40 airline miles from the principal city in such area; or"],[1,"(10)(A) any salesman, partsman, or mechanic primarily engaged in selling or servicing automobiles, trucks, or farm implements, if he is employed by a nonmanufacturing establishment primarily engaged in the business of selling such vehicles or implements to ultimate purchasers; or"],[1,"(B) any salesman primarily engaged in selling trailers, boats, or aircraft, if he is employed by a nonmanufacturing establishment primarily engaged in the business of selling trailers, boats, or aircraft to ultimate purchasers; or"],[1,"(11) any employee employed as a driver or driver's helper making local deliveries, who is compensated for such employment on the basis of trip rates, or other delivery payment plan, if the Secretary shall find that such plan has the general purpose and effect of reducing hours worked by such employees to, or below, the maximum workweek applicable to them under section 207(a) of this title; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/213?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§213. Exemptions","tname":"Labor","by":{"0":"passim","1":"6","2":"2, 1, 2, 3, 1, 2"}},{"t":"usc","label":"29 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/29/216","subs":["(b)","(c)"],"stext":{"head":"§216. Penalties","paras":[[0,"(a) Fines and imprisonment"],[0,"Any person who willfully violates any of the provisions of section 215 of this title shall upon conviction thereof be subject to a fine of not more than $10,000, or to imprisonment for not more than six months, or both. No person shall be imprisoned under this subsection except for an offense committed after the conviction of such person for a prior offense under this subsection."],[0,"(b) Damages; right of action; attorney's fees and costs; termination of right of action"],[0,"Any employer who violates the provisions of section 206 or section 207 of this title shall be liable to the employee or employees affected in the amount of their unpaid minimum wages, or their unpaid overtime compensation, as the case may be, and in an additional equal amount as liquidated damages. Any employer who violates the provisions of section 215(a)(3) or 218d of this title shall be liable for such legal or equitable relief as may be appropriate to effectuate the purposes of section 215(a)(3) or 218d of this title, including without limitation employment, reinstatement, promotion, and the payment of wages lost and an additional equal amount as liquidated damages. Any employer who violates section 203(m)(2)(B) of this title shall be liable to the employee or employees affected in the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and in an additional equal amount as liquidated damages. An action to recover the liability prescribed in the preceding sentences may be maintained against any employer (including a public agency) in any Federal or State court of competent jurisdiction by any one or more employees for and in behalf of himself or themselves and other employees similarly situated. No employee shall be a party plaintiff to any such action unless he gives his consent in writing to become such a party and such consent is filed in the court in which such action is brought. The court in such action shall, in addition to any judgment awarded to the plaintiff or plaintiffs, allow a reasonable attorney's fee to be paid by the defendant, and costs of the action. The right provided by this subsection to bring an action by or on behalf of any employee, and the right of any employee to become a party plaintiff to any such action, shall terminate upon the filing of a complaint by the Secretary of Labor in an action under section 217 of this title in which (1) restraint is sought of any further delay in the payment of unpaid minimum wages, or the amount of unpaid overtime compensation, as the case may be, owing to such employee under section 206 or section 207 of this title by an employer liable therefor under the provisions of this subsection or (2) legal or equitable relief is sought as a result of alleged violations of section 215(a)(3) or 218d of this title."],[0,"(c) Payment of wages and compensation; waiver of claims; actions by the Secretary; limitation of actions"],[0,"The Secretary is authorized to supervise the payment of the unpaid minimum wages or the unpaid overtime compensation owing to any employee or employees under section 206 or section 207 of this title, and the agreement of any employee to accept such payment shall upon payment in full constitute a waiver by such employee of any right he may have under subsection (b) of this section to such unpaid minimum wages or unpaid overtime compensation and an additional equal amount as liquidated damages. The Secretary may bring an action in any court of competent jurisdiction to recover the amount of unpaid minimum wages or overtime compensation and an equal amount as liquidated damages. The right provided by subsection (b) to bring an action by or on behalf of any employee to recover the liability specified in the first sentence of such subsection and of any employee to become a party plaintiff to any such action shall terminate upon the filing of a complaint by the Secretary in an action under this subsection in which a recovery is sought of unpaid minimum wages or unpaid overtime compensation under sections 206 and 207 of this title or liquidated or other damages provided by this subsection owing to such employee by an employer liable under the provisions of subsection (b), unless such action is dismissed without prejudice on motion of the Secretary. Any sums thus recovered by the Secretary of Labor on behalf of an employee pursuant to this subsection shall be held in a special deposit account and shall be paid, on order of the Secretary of Labor, directly to the employee or employees affected. Any such sums not paid to an employee because of inability to do so within a period of three years shall be covered into the Treasury of the United States as miscellaneous receipts. In determining when an action is commenced by the Secretary of Labor under this subsection for the purposes of the statutes of limitations provided in section 6(a) of the Portal-to-Portal Act of 1947 [29 U.S.C. 255(a)], it shall be considered to be commenced in the case of any individual claimant on the date when the complaint is filed if he is specifically named as a party plaintiff in the complaint, or if his name did not so appear, on the subsequent date on which his name is added as a party plaintiff in such action. The authority and requirements described in this subsection shall apply with respect to a violation of section 203(m)(2)(B) of this title, as appropriate, and the employer shall be liable for the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and an additional equal amount as liquidated damages."],[0,"(d) Savings provisions"],[0,"In any action or proceeding commenced prior to, on, or after August 8, 1956, no employer shall be subject to any liability or punishment under this chapter or the Portal-to-Portal Act of 1947 [29 U.S.C. 251 et seq.] on account of his failure to comply with any provision or provisions of this chapter or such Act (1) with respect to work heretofore or hereafter performed in a workplace to which the exemption in section 213(f) of this title is applicable, (2) with respect to work performed in Guam, the Canal Zone or Wake Island before the effective date of this amendment of subsection (d), or (3) with respect to work performed in a possession named in section 206(a)(3) 1 of this title at any time prior to the establishment by the Secretary, as provided therein, of a minimum wage rate applicable to such work."],[0,"(e) Civil penalties for certain violations"],[0,"(1)(A) Any person who violates the provisions of sections 2 212 or 213(c) of this title, relating to child labor, or any regulation issued pursuant to such sections, shall be subject to a civil penalty not to exceed—"],[1,"(i) $11,000 for each employee who was the subject of such a violation; or"],[1,"(ii) $50,000 with regard to each such violation that causes the death or serious injury of any employee under the age of 18 years, which penalty may be doubled where the violation is a repeated or willful violation."],[0,"(B) For purposes of subparagraph (A), the term \"serious injury\" means—"],[1,"(i) permanent loss or substantial impairment of one of the senses (sight, hearing, taste, smell, tactile sensation);"],[1,"(ii) permanent loss or substantial impairment of the function of a bodily member, organ, or mental faculty, including the loss of all or part of an arm, leg, foot, hand or other body part; or"],[1,"(iii) permanent paralysis or substantial impairment that causes loss of movement or mobility of an arm, leg, foot, hand or other body part."],[0,"(2) Any person who repeatedly or willfully violates section 206 or 207 of this title, relating to wages, shall be subject to a civil penalty not to exceed $1,100 for each such violation. Any person who violates section 203(m)(2)(B) of this title shall be subject to a civil penalty not to exceed $1,100 for each such violation, as the Secretary determines appropriate, in addition to being liable to the employee or employees affected for all tips unlawfully kept, and an additional equal amount as liquidated damages, as described in subsection (b)."],[0,"(3) In determining the amount of any penalty under this subsection, the appropriateness of such penalty to the size of the business of the person charged and the gravity of the violation shall be considered. The amount of any penalty under this subsection, when finally determined, may be—"],[1,"(A) deducted from any sums owing by the United States to the person charged;"],[1,"(B) recovered in a civil action brought by the Secretary in any court of competent jurisdiction, in which litigation the Secretary shall be represented by the Solicitor of Labor; or"],[1,"(C) ordered by the court, in an action brought for a violation of section 215(a)(4) of this title or a repeated or willful violation of section 215(a)(2) of this title, to be paid to the Secretary."],[0,"(4) Any administrative determination by the Secretary of the amount of any penalty under this subsection shall be final, unless within 15 days after receipt of notice thereof by certified mail the person charged with the violation takes exception to the determination that the violations for which the penalty is imposed occurred, in which event final determination of the penalty shall be made in an administrative proceeding after opportunity for hearing in accordance with section 554 of title 5 and regulations to be promulgated by the Secretary."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/216?type=usc&year=mostrecent&link-type=html"},"head":"§216. Penalties","tname":"Labor","by":{"0":"5","2":"1"}},{"t":"law","label":"Pub. L. No. 87-30","url":"https://www.govinfo.gov/link/statute/75/65","by":{"0":"6"}},{"t":"reg","label":"29 C.F.R. § 541.0","url":"https://www.ecfr.gov/current/title-29/section-541.0","by":{"0":"46"}},{"t":"reg","label":"29 C.F.R. § 541.3","url":"https://www.ecfr.gov/current/title-29/section-541.3","by":{"0":"31","1":"36, 37"}},{"t":"reg","label":"29 C.F.R. § 541.100","url":"https://www.ecfr.gov/current/title-29/section-541.100","subs":["(a)"],"by":{"0":"6, 46, 6, 7, 17"}},{"t":"reg","label":"29 C.F.R. § 541.118","url":"https://www.ecfr.gov/current/title-29/section-541.118","subs":["(a)(1)","(a)(6)","(b)"],"by":{"0":"31","1":"7, 38, 38, 38, 8, 23, 23, 23, 23"}},{"t":"reg","label":"29 C.F.R. § 541.200","url":"https://www.ecfr.gov/current/title-29/section-541.200","subs":["(a)"],"by":{"0":"6, 6"}},{"t":"reg","label":"29 C.F.R. § 541.300","url":"https://www.ecfr.gov/current/title-29/section-541.300","subs":["(a)"],"by":{"0":"6, 6"}},{"t":"reg","label":"29 C.F.R. § 541.400","url":"https://www.ecfr.gov/current/title-29/section-541.400","by":{"0":"37"}},{"t":"reg","label":"29 C.F.R. § 541.500","url":"https://www.ecfr.gov/current/title-29/section-541.500","by":{"0":"37"}},{"t":"reg","label":"29 C.F.R. § 541.600","url":"https://www.ecfr.gov/current/title-29/section-541.600","subs":["(a)"],"by":{"0":"9","1":"20, 10, 29"}},{"t":"reg","label":"29 C.F.R. § 541.601","url":"https://www.ecfr.gov/current/title-29/section-541.601","subs":["(a)","(b)","(d)","(b)(1)","(b)(2)"],"op":1,"by":{"0":"1, 12, 21, 25, 13, 29, passim, 30, 13, 31, 44","1":"passim, 33, 10, 11, 29, 39, 36, 37"}},{"t":"reg","label":"29 C.F.R. § 541.602","url":"https://www.ecfr.gov/current/title-29/section-541.602","subs":["(a)","(a)(3)(i)","(a)(1)","(a)(3)","(b)","(b)(6)"],"by":{"0":"10, 12, 8, 25, 36","1":"passim, passim, 12, 11, 7, 40, 21"}},{"t":"reg","label":"29 C.F.R. § 541.604","url":"https://www.ecfr.gov/current/title-29/section-541.604","subs":["(a)","(b)"],"op":1,"by":{"0":"passim, 9, passim","1":"passim, 9, 21, 33, 37, 38, passim"}},{"t":"reg","label":"29 C.F.R. § 541.605","url":"https://www.ecfr.gov/current/title-29/section-541.605","by":{"0":"8","1":"21, 32"}},{"t":"reg","label":"Defining and Delimiting the Exemptions for Executive, Administrative, Professional, Outside Sales and Computer Employees, 69 Fed. Reg. 22,122","url":"https://www.govinfo.gov/link/fr/69/22122","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"reg","label":"Defining and Delimiting the Exemptions for Executive, Administrative, Professional, Outside Sales and Computer Employees, 84 Fed. Reg. 51,230","url":"https://www.govinfo.gov/link/fr/84/51230","by":{"0":"14, 33","1":"32","2":"2, 3"}},{"t":"case","label":"Auer v. Robbins","cite":"519 U.S. 452","y":1997,"id":"1996/95-897","sc":1,"sum":"Authored by Justice Antonin Scalia, the Court ruled that sergeants and lieutenants are exempt as salaried employees from the federal Fair Labor Standards Act. The justices rejected the argument that the possibility of suspension without pay moves the officers out of the exempt category.","sumSrc":"Oyez","by":{"1":"6, 27, 45","2":"22, 31, 32"}},{"t":"case","label":"Batterton v. Francis","cite":"432 U.S. 416","y":1977,"id":"1976/75-1181","sc":1,"sum":"The regulation is a proper exercise of the Secretary's statutory authority and is reasonable.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45"}},{"t":"case","label":"Biden v. Texas","cite":"142 S. Ct. 2528","y":2022,"id":"2021/21-954","sc":1,"sum":"The Government’s rescission of Migrant Protection Protocols did not violate section 1225 of the Immigration and Nationality Act, and the then-Secretary of Homeland Security’s October 29 Memoranda constituted valid final agency action.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"35"}},{"t":"case","label":"Chevron U.S.A. Inc. v. Natural Resources Defense Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"1":"4, 6, 18, 45"}},{"t":"case","label":"City of Chicago v. Envt’l Def. Fund","cite":"511 U.S. 328","y":1994,"id":"1993/92-1639","sc":1,"sum":"Section 3001(i) does not exempt the MWC ash generated by petitioners' facility from Subtitle C regulation as hazardoug waste. Although a pre-§ 3001(i) EPA regulation provided a \"waste stream\" exemption covering household waste from generation through treatment to final disposal of residues, petitioners' facility would not have come within that exemption because it burned something in addition to household waste; the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Coeur Alaska, Inc. v. Southeast Alaska Conservation Council","cite":"557 U.S. 261","y":2009,"id":"2008/07-984","sc":1,"sum":"The Court held that the United States Army Corps of Engineers had exclusive rights to grant a permit to Coeur Alaska, Inc. to discharge its waste.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Davis v. J.P. Morgan Chase","cite":"587 F.3d 529","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/587/529/","by":{"1":"5, 6"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Fid. Fed. Sav. and Loan Ass’n v. de la Cuesta","cite":"458 U.S. 141","y":1982,"id":"1981/81-750","sc":1,"sum":"The Board's due-on-sale regulation pre-empts conflicting state limitations on the due-on-sale practices of federal savings and loan associations, and thus bars application of the Wellenkamp rule to such associations.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Gardner v. G.D. Barri & Assocs., Inc.","cite":"2022 WL 3042857","y":2022,"court":"D. Ariz. Aug. 2","by":{"1":"41"}},{"t":"case","label":"Idaho Sheet Metal Works, Inc. v. Wirtz","cite":"383 U.S. 190","y":1966,"id":"1965/30","sc":1,"sum":"In No. 30 the employer, petitioner, has 12 workers who fabricate, install and repair sheet metal products. While about 60% of sales in number are to the general public, about 83% of gross income comes from Work done, generally on individual specifications for sizable pieces of equipment, for five potato processing companies which dehydrate and freeze potatoes for interstate shipment. In reply to respondent's claim …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"6"}},{"t":"case","label":"Kimbrough v. United States","cite":"552 U.S. 85","y":2007,"id":"2007/06-6330","sc":1,"sum":"Justice Ruth Bader Ginsburg authored the Court's 7-2 majority opinion reversing the Fourth Circuit and affirming the sentence handed down by the trial judge. Ginsburg noted that the drug trafficking statute still had some minimum sentencing requirements, and expressed the Court's confidence that district courts could maintain reasonably uniform approaches to cocaine sentencing.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Kingdomware Techs., Inc. v. United States","cite":"579 U.S. 162","y":2016,"id":"2015/14-916","sc":1,"op":1,"sum":"The Court determined that the Court had jurisdiction to address the merits of the case even if the contracts had already been performed, and the Department of Veterans Affairs’ “set-aside” for veteran-owned businesses is mandatory.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"27","2":"22"}},{"t":"case","label":"Landgraf v. USI Film Products","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49"}},{"t":"case","label":"Mechmet v. Four Seasons Hotels, Ltd.","cite":"825 F.2d 1173","y":1987,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/825/1173/","by":{"1":"47"}},{"t":"case","label":"Nevada v. U.S. Dep’t of Lab.","cite":"218 F. Supp. 3d 520","y":2016,"court":"E.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/218/520/","by":{"1":"11"}},{"t":"case","label":"Nichols v. United States","cite":"578 U.S. 104","y":2016,"id":"2015/15-5238","sc":1,"sum":"The Court determined that the Sexual Offender Registration and Notification Act does not require a sex offender who is moving to a country outside of U.S. jurisdiction to update his residence with the sexual offender registry.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"OBB Personenverkher AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"sum":"The Court held that the commercial activity exception to the Foreign Sovereign Immunity Act only applies when the suit is based upon activity that took place in the United States, and it was not sufficient to establish a single element of the claim in question.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Overnight Motor Transp. Co. v. Missel","cite":"316 U.S. 572","y":1942,"id":"scdb/1941-060","sc":1,"op":1,"sum":"1. An employee of an interstate motor transportation company, who acted as rate clerk and performed other incidental duties, held \"engaged in commerce\" within the meaning of § 7 of the Fair Labor Standards Act of 1938, and entitled to the benefit of its overtime provisions.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47","2":"2"}},{"t":"case","label":"Rotkiske v. Kelmm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"Stout v. Universal Ensco, Inc.","cite":"2012 WL 13124740","y":2012,"court":"S.D. Tex. Sept. 18","by":{"1":"50"}},{"t":"reg","label":"29 C.F.R. § 541.101","url":"https://www.ecfr.gov/current/title-29/section-541.101","by":{"1":"35"}},{"t":"reg","label":"29 C.F.R. § 541.117","url":"https://www.ecfr.gov/current/title-29/section-541.117","subs":["(a)"],"by":{"1":"23, 23, 23"}},{"t":"reg","label":"29 C.F.R. § 541.119","url":"https://www.ecfr.gov/current/title-29/section-541.119","subs":["(a)"],"by":{"1":"34"}},{"t":"reg","label":"29 C.F.R. § 541.304","url":"https://www.ecfr.gov/current/title-29/section-541.304","subs":["(d)"],"by":{"1":"35"}},{"t":"reg","label":"29 C.F.R. § 541.603","url":"https://www.ecfr.gov/current/title-29/section-541.603","by":{"1":"passim"}},{"t":"reg","label":"29 C.F.R. § 541.709","url":"https://www.ecfr.gov/current/title-29/section-541.709","by":{"1":"35"}},{"t":"reg","label":"29 C.F.R. § 542.118","url":"https://www.ecfr.gov/current/title-29/section-542.118","by":{"1":"38"}},{"t":"reg","label":"5 Fed. Reg. 4,071","url":"https://www.govinfo.gov/link/fr/5/4071","by":{"1":"6"}},{"t":"reg","label":"14 Fed. Reg. 7,730","url":"https://www.govinfo.gov/link/fr/14/7730","by":{"1":"10"}},{"t":"reg","label":"19 Fed. Reg. 4,397","url":"https://www.govinfo.gov/link/fr/19/4397","by":{"1":"38"}},{"t":"reg","label":"46 Fed. Reg. 2,969","url":"https://www.govinfo.gov/link/fr/46/2969","by":{"1":"23"}},{"t":"reg","label":"49 Fed. Reg. 7,730","url":"https://www.govinfo.gov/link/fr/49/7730","by":{"1":"8, 23"}},{"t":"reg","label":"Defining and Delimiting the Exemptions for Executive, Administrative, Professional, Outside Sales and Computer Employees, 81 Fed. Reg. 32,391","url":"https://www.govinfo.gov/link/fr/81/32391","by":{"1":"5, 6, 46"}},{"t":"case","label":"Craig v. Far W. Eng’g Co.","cite":"265 F.2d 251","y":1959,"url":"https://www.courtlistener.com/c/F.2d/265/251/","by":{"2":"17, 32"}},{"t":"case","label":"Fanelli v. United States Gypsum Co.","cite":"141 F.2d 216","y":1944,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/141/216/","by":{"2":"32"}},{"t":"case","label":"Helliwell v. Haberman","cite":"140 F.2d 833","y":1944,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/140/833/","by":{"2":"32"}},{"t":"case","label":"Mitchell v. Kentucky Fin. Co.","cite":"359 U.S. 290","y":1959,"id":"1958/161","sc":1,"sum":"The business of making small personal loans and purchasing conditional sales contracts from dealers in furniture and appliances does not constitute \"sales of...services\" by a \"retail or service establishment,\" within the meaning of the exemption provided in § 13 (a) (2) of the Fair Labor Standards Act, as amended in 1949. Pp. 290-296. 254-F. 2d 8, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"32"}},{"t":"case","label":"Reich v. Waldbaum, Inc.","cite":"52 F.3d 35","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/52/35/","sum":"Concluding that “the law [is] clear” that “employees compensated on an hourly basis” do not satisfy the “salary basis” test.","sumSrc":"brief:2","by":{"2":"17"}},{"t":"case","label":"Steiner v. Mitchell","cite":"350 U.S. 247","y":1956,"id":"1955/22","sc":1,"sum":"Changing clothes and showering are parts of their \"principal,\" rather than their \"preliminary\" or \"postliminary,\" activities, within the meaning of § 4 (a) (2) of the -Portal-to-Portal Act, and the time spent in these activities must be counted in measuring the work-time for which compensation is required by the Fair Labor Standards Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"32"}},{"t":"case","label":"Walling v. Morris","cite":"155 F.2d 832","y":1946,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/155/832/","sum":"Explaining that regulations’ validity was “well established”.","sumSrc":"brief:2","by":{"2":"32"}},{"t":"case","label":"Walling v. Yeakley","cite":"140 F.2d 830","y":1944,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/140/830/","by":{"2":"32"}},{"t":"case","label":"Wirtz v. Mississippi Publishers Corp.","cite":"364 F.2d 603","y":1966,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/364/603/","by":{"2":"32"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"2":"1"}},{"t":"usc","label":"29 U.S.C. § 204","url":"https://www.law.cornell.edu/uscode/text/29/204","by":{"2":"1"}},{"t":"usc","label":"29 U.S.C. § 211","url":"https://www.law.cornell.edu/uscode/text/29/211","subs":["(a)"],"by":{"2":"1"}},{"t":"usc","label":"29 U.S.C. § 217","url":"https://www.law.cornell.edu/uscode/text/29/217","by":{"2":"1"}},{"t":"reg","label":"12 Fed. Reg. 6896","url":"https://www.govinfo.gov/link/fr/12/6896","by":{"2":"5"}},{"t":"reg","label":"14 Fed. Reg. 5573","url":"https://www.govinfo.gov/link/fr/14/5573","by":{"2":"5"}},{"t":"reg","label":"14 Fed. Reg. 7723","url":"https://www.govinfo.gov/link/fr/14/7723","by":{"2":"5"}},{"t":"reg","label":"68 Fed. Reg. 15,560","url":"https://www.govinfo.gov/link/fr/68/15560","by":{"2":"20"}}]};